fn solve_rival_distance(n: i8, x: i8, a: i8, b: i8) -> i8 {
    // Calculate the initial distance between positions a and b
    let initial_distance = (a - b).abs();
    
    // Calculate the maximum possible distance after performing up to x moves
    let max_distance = initial_distance + x;
    
    // The maximum distance cannot exceed n - 1
    let result = max_distance.min(n - 1);
    
    result
}

fn main() {
    // Example usage
    let n = 10;
    let x = 3;
    let a = 2;
    let b = 5;
    
    let result = solve_rival_distance(n, x, a, b);
    println!("Maximum possible distance: {}", result);
}